package com.gestordevendas.api.food;
import com.gestordevendas.api.company.Company; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="couriers") public class Courier { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="company_id") private Company company; @Column(nullable=false) private String name; private String phone; @Column(name="delivery_fee",nullable=false) private BigDecimal deliveryFee; protected Courier(){} public static Courier create(Company c,String n,String p,BigDecimal fee){var x=new Courier();x.id=UUID.randomUUID();x.company=c;x.update(n,p,fee);return x;} public void update(String n,String p,BigDecimal fee){name=n;phone=p;deliveryFee=fee;} public UUID getId(){return id;} public String getName(){return name;} public String getPhone(){return phone;} public BigDecimal getDeliveryFee(){return deliveryFee;} }